#!/bin/bash
# Lancé depuis un dossier de travail temporaire contenant base.png.
P='SUBJECT: an antique engraved map of metropolitan France with Corsica, seen from above. Keep EXACTLY the coastline, borders and proportions of France from the composition reference. Vineyards appear ONLY where the reference shows gold dots: draw them there as tiny engraved vine rows and small grape motifs, following the dense clusters (Bordeaux, Loire valley, Champagne, Alsace, Burgundy, Beaujolais, Jura, Savoie, Rhone valley, Provence, Languedoc-Roussillon, South-West, Corsica). Everywhere else in France: plain paper with only light relief hatching, rivers and forests, absolutely no vines. A delicate dotted travel route from Paris to the Alps, a small ornamental compass rose in the sea at bottom left, a thin decorative cartouche border. STYLE: fine copperplate engraving and etching like a classic French wine label illustration. Two-tone ink only: deep bordeaux (#5B1428) and antique gold (#8A6D2F) on warm off-white paper (#F7F3EE). Precise line work, cross-hatching, elegant and calm. No gradients, no photorealism, no 3D. CONSTRAINTS: no text, no letters, no place names, no numbers, no watermark.'
chatgpt-imagegen "$P" -o carte-a-composition.png --composition-ref base.png --style-ref ../hero-2-carte.png --backend codex --size 1536x1024 --quiet --no-progress 2> a.err && echo ok-a || echo "FAIL a $(tail -c 300 a.err)"
chatgpt-imagegen "Redraw this map image as described. $P" -o carte-b-edition.png -i base.png --action edit --backend codex --size 1536x1024 --quiet --no-progress 2> b.err && echo ok-b || echo "FAIL b $(tail -c 300 b.err)"
echo DONE
